/* Auto-theorie B — modules 1, 3, 4, 6, 7 en 8.
   Bronnen: RVV 1990, WVW 1994, Reglement rijbewijzen, Regeling voertuigen. */
window.MODULES2 = [
{
  id:'weg', nr:1, titel:'Gebruik van de weg', kleur:'--m-weg',
  samenvatting:'Plaats op de weg, snelheden, inhalen, afstand houden, stilstaan en parkeren.',
  lessons:[
    {t:'Rechts houden', b:'Je houdt zoveel mogelijk rechts. Op een weg met rijstroken binnen de bebouwde kom mag je vrij een rijstrook kiezen; buiten de bebouwde kom gebruik je de rechterstrook en de linker alleen om in te halen.', a:'RVV 1990, art. 3'},
    {t:'Waar rijd je met welk voertuig', b:'Motorvoertuigen horen op de rijbaan. Fietsers en bromfietsers gebruiken het fietspad of fiets/bromfietspad als dat er is. Voetgangers lopen op het trottoir of, als dat ontbreekt, zoveel mogelijk links langs de weg.', a:'RVV 1990, art. 3, 4 en 10'},
    {t:'Maximumsnelheden voor een personenauto', b:'Bebouwde kom 50. Buiten de bebouwde kom 80. Autoweg 100. Autosnelweg 100 tussen 06.00 en 19.00 uur, daarbuiten wat op de borden staat. Erf 15. Borden gaan altijd voor deze standaardwaarden.', a:'RVV 1990, art. 20, 21 en 45'},
    {t:'Met een aanhanger of caravan', b:'Met een aanhangwagen rijd je op de autosnelweg en autoweg maximaal 90 km/h en op andere wegen buiten de bebouwde kom maximaal 80 km/h.', a:'RVV 1990, art. 22'},
    {t:'Inhalen doe je links', b:'Je haalt links in. Rechts inhalen mag als de voorligger duidelijk heeft aangegeven linksaf te slaan, en op rijstroken waar het verkeer in rijen rijdt en jouw rij sneller gaat.', a:'RVV 1990, art. 11'},
    {t:'Waar je niet mag inhalen', b:'Niet vlak voor of op een zebrapad, niet vlak voor of op een spoorwegovergang, en niet waar bord F1 of F3 staat of een doorgetrokken streep ligt.', a:'RVV 1990, art. 11, 12 en 76'},
    {t:'Afstand houden', b:'Hou zoveel afstand dat je kunt stoppen als de voorligger plotseling remt. De vuistregel is twee seconden; bij regen, mist of een zware auto maak je er drie van.', a:'RVV 1990, art. 19'},
    {t:'Stilstaan mag niet overal', b:'Niet op een kruispunt, op een overweg, op een zebrapad of binnen vijf meter ervoor, langs een gele doorgetrokken streep, in een tunnel of op de rijbaan van een autosnelweg of autoweg.', a:'RVV 1990, art. 23'},
    {t:'Parkeren mag nog minder vaak', b:'Niet bij een kruispunt binnen vijf meter, niet voor een inrit of uitrit, niet langs een gele onderbroken streep, niet op een gehandicaptenplaats zonder kaart en niet zo dat je anderen hindert.', a:'RVV 1990, art. 24'},
    {t:'Verlichting', b:'Bij duisternis en bij slecht zicht voer je dimlicht. Mistlicht achter mag alleen als het zicht minder is dan 50 meter. Overdag is dagrijverlichting verplicht op auto’s die er vanaf fabriek mee zijn uitgerust.', a:'RVV 1990, art. 32 t/m 36'},
    {t:'Gordels en kinderen', b:'Iedereen in de auto draagt een gordel. Kinderen kleiner dan 1,35 meter zitten in een goedgekeurd kinderzitje. Jij als bestuurder bent verantwoordelijk voor passagiers onder de 18.', a:'RVV 1990, art. 59 en 60'},
    {t:'Telefoon vasthouden mag niet', b:'Je mag tijdens het rijden geen mobiel elektronisch apparaat vasthouden. Handsfree bellen mag, maar ook dat kost aandacht.', a:'RVV 1990, art. 61a'}
  ],
  questions:[
    {t:'mc', v:'Wat is de maximumsnelheid voor een personenauto buiten de bebouwde kom op een gewone weg?', o:['50 km/h','70 km/h','80 km/h','100 km/h'], a:2, u:'Buiten de bebouwde kom geldt standaard 80 km/h, tenzij borden iets anders aangeven.', art:'RVV 1990, art. 21'},
    {t:'mc', v:'Op vrijwel alle Nederlandse autosnelwegen geven de borden tussen 06.00 en 19.00 uur dezelfde maximumsnelheid aan. Welke?', o:['80 km/h','100 km/h','120 km/h','130 km/h'], a:1, u:'Sinds 2020 geldt overdag op vrijwel het hele hoofdwegennet 100 km/h, aangegeven met borden A1. ’s Avonds en ’s nachts staat op de borden wat daar geldt. Kijk dus altijd naar de bebording.', art:'RVV 1990, art. 21 jo. de borden A1'},
    {t:'mc', v:'Je rijdt met een caravan op de autosnelweg. Wat is je maximumsnelheid?', o:['80 km/h','90 km/h','100 km/h','Hetzelfde als zonder caravan'], a:1, u:'Met een aanhangwagen of caravan rijd je maximaal 90 km/h op de autosnelweg en autoweg.', art:'RVV 1990, art. 22'},
    {t:'jn', v:'Op een erf mag je maximaal 30 km/h rijden.', a:1, u:'Nee, op een erf rijd je stapvoets: maximaal 15 km/h.', art:'RVV 1990, art. 45'},
    {t:'mc', v:'Wanneer mag je rechts inhalen?', o:['Nooit','Als de voorligger heeft aangegeven linksaf te slaan','Als je haast hebt','Alleen op de autosnelweg'], a:1, u:'Rechts inhalen mag als de bestuurder voor je duidelijk heeft aangegeven linksaf te willen slaan, en bij rijen verkeer op rijstroken.', art:'RVV 1990, art. 11'},
    {t:'multi', v:'Waar mag je niet inhalen?', o:['Vlak voor een zebrapad','Op een spoorwegovergang','Op een driebaansweg','Waar bord F1 staat','Bij een doorgetrokken streep aan jouw kant'], a:[0,1,3,4], u:'Een zebrapad, een overweg, bord F1 en een doorgetrokken streep aan jouw kant sluiten inhalen uit.', art:'RVV 1990, art. 11, 12 en 76'},
    {t:'fill', v:'Hoeveel seconden afstand hou je als vuistregel bij droog weer? (cijfer of woord)', a:'twee', u:'Twee seconden bij droog weer, drie bij regen of mist. Tel na een vast punt: eenentwintig, tweeentwintig.', art:'Rijtechnische vuistregel'},
    {t:'mc', v:'Wanneer mag je je mistlicht achter gebruiken?', o:['Altijd bij regen','Bij zicht minder dan 50 meter','Bij zicht minder dan 200 meter','In het donker'], a:1, u:'Mistlicht achter mag alleen als het zicht door mist, sneeuw of regen minder is dan 50 meter. Bij beter zicht verblind je er anderen mee.', art:'RVV 1990, art. 34 lid 2'},
    {t:'jn', v:'Je mag stilstaan op een zebrapad om iemand te laten uitstappen.', a:1, u:'Nee. Stilstaan op of binnen vijf meter voor een zebrapad is verboden.', art:'RVV 1990, art. 23'},
    {t:'mc', v:'Je ziet een gele onderbroken streep langs de stoeprand. Wat betekent dat?', o:['Parkeerverbod','Stilstaanverbod','Laad- en loszone','Fietsstrook'], a:0, u:'Een gele onderbroken streep is een parkeerverbod. Een gele doorgetrokken streep verbiedt ook stilstaan.', art:'RVV 1990, art. 24 en 23'},
    {t:'mc', v:'Tot welke lengte moet een kind in een goedgekeurd kinderzitje?', o:['1,20 meter','1,35 meter','1,50 meter','Tot 12 jaar, ongeacht lengte'], a:1, u:'Kinderen kleiner dan 1,35 meter horen in een goedgekeurd kinderbeveiligingssysteem.', art:'RVV 1990, art. 59'},
    {t:'jn', v:'Handsfree bellen tijdens het rijden is toegestaan.', a:0, u:'Ja, handsfree mag. Het apparaat vasthouden mag niet. Houd er rekening mee dat bellen altijd aandacht kost.', art:'RVV 1990, art. 61a'},
    {t:'mc', v:'Buiten de bebouwde kom rijd je op een weg met twee rijstroken in jouw richting. Waar hoor je te rijden?', o:['Op de linkerstrook','Op de rechterstrook; links alleen om in te halen','Maakt niet uit','Op de strook met de minste auto’s'], a:1, u:'Buiten de bebouwde kom hou je rechts en gebruik je de linkerstrook alleen om in te halen.', art:'RVV 1990, art. 3'},
    {t:'mc', v:'Wie is verantwoordelijk als een passagier van 15 jaar geen gordel draagt?', o:['De passagier','De bestuurder','Allebei evenveel','Niemand'], a:1, u:'Voor passagiers jonger dan 18 is de bestuurder verantwoordelijk. Vanaf 18 is de passagier zelf aansprakelijk.', art:'RVV 1990, art. 59'},
    {t:'multi', v:'Waar mag je niet parkeren?', o:['Binnen vijf meter van een kruispunt','Voor een uitrit','In een parkeervak','Op een gehandicaptenplaats zonder kaart','Langs een gele onderbroken streep'], a:[0,1,3,4], u:'Alleen parkeren in een gewoon parkeervak is hier toegestaan.', art:'RVV 1990, art. 24'},
    {t:'jn', v:'Voetgangers moeten links langs de weg lopen als er geen trottoir is.', a:0, u:'Ja. Zonder trottoir of voetpad loop je zoveel mogelijk links, zodat je het tegemoetkomende verkeer ziet aankomen.', art:'RVV 1990, art. 4'},
    {t:'mc', v:'Je nadert een file op de autosnelweg. Wat is verstandig?', o:['Hard doorrijden tot vlak voor de file','Alarmlichten aanzetten en rustig afremmen','Naar de vluchtstrook uitwijken','Claxonneren'], a:1, u:'Met je alarmlichten waarschuw je het verkeer achter je. Rem geleidelijk en kijk in je spiegel.', art:'WVW 1994, art. 5 en RVV 1990, art. 19'},
    {t:'mc', v:'Hoe hard mag een personenauto met aanhanger buiten de bebouwde kom op een gewone weg?', o:['70 km/h','80 km/h','90 km/h','100 km/h'], a:1, u:'Op gewone wegen buiten de bebouwde kom is dat 80 km/h; op autoweg en autosnelweg 90.', art:'RVV 1990, art. 22'},
    {t:'jn', v:'Je mag op de vluchtstrook stoppen om de route op te zoeken.', a:1, u:'Nee. De vluchtstrook is alleen voor noodgevallen, zoals pech of een ongeval.', art:'RVV 1990, art. 43'},
    {t:'mc', v:'Op een weg binnen de bebouwde kom met twee rijstroken in jouw richting mag je:', o:['Alleen rechts rijden','Vrij een rijstrook kiezen','Alleen links rijden','Alleen rechts, behalve bij inhalen'], a:1, u:'Binnen de bebouwde kom mag je op een weg met meerdere rijstroken vrij kiezen welke strook je gebruikt.', art:'RVV 1990, art. 3'},
    {t:'fill', v:'Wat is de standaard maximumsnelheid binnen de bebouwde kom voor een personenauto? (alleen het getal)', a:'50', u:'Binnen de bebouwde kom geldt 50 km/h, tenzij borden iets anders aangeven, zoals een 30-zone.', art:'RVV 1990, art. 20'},
    {t:'mc', v:'Wanneer moet je dimlicht voeren?', o:['Alleen ’s nachts','Bij duisternis en bij slecht zicht overdag','Alleen buiten de bebouwde kom','Alleen op de snelweg'], a:1, u:'Bij duisternis en bij slecht zicht, bijvoorbeeld door regen, mist of sneeuw, is dimlicht verplicht.', art:'RVV 1990, art. 32'},
    {t:'jn', v:'Je mag met groot licht blijven rijden als er een tegenligger aankomt.', a:1, u:'Nee. Je dimt tijdig voor tegenliggers en ook als je dicht achter een voorligger rijdt.', art:'RVV 1990, art. 32 lid 2'},
    {t:'mc', v:'Je staat stil voor een rood licht. Mag je je telefoon in je hand pakken?', o:['Ja, je rijdt niet','Nee, het verbod geldt ook als je stilstaat in het verkeer','Alleen om te navigeren','Alleen om te bellen'], a:1, u:'Het verbod geldt voor bestuurders van een rijdend én stilstaand voertuig in het verkeer, dus ook voor het stoplicht.', art:'RVV 1990, art. 61a'},
    {t:'mc', v:'Twee rijen verkeer rijden naast elkaar op rijstroken. Jouw rij rijdt sneller dan de rij links. Wat is waar?', o:['Dit is verboden rechts inhalen','Dit mag; het is geen inhalen','Je moet afremmen','Alleen toegestaan in file'], a:1, u:'Als het verkeer in rijen rijdt, is sneller gaan dan de rij naast je geen inhalen.', art:'RVV 1990, art. 11'},
    {t:'multi', v:'Wat hoort bij veilig gebruik van de weg?', o:['Zoveel mogelijk rechts houden','Twee seconden afstand','Links rijden omdat het sneller gaat','Richting aangeven voor elke manoeuvre','Dimmen voor tegenliggers'], a:[0,1,3,4], u:'Links blijven rijden zonder in te halen is zowel hinderlijk als verboden buiten de bebouwde kom.', art:'RVV 1990, art. 3, 19, 32 en 55'},
    {t:'jn', v:'Een fietser mag op de rijbaan rijden als er een verplicht fietspad (G11) is.', a:1, u:'Nee. Bij een verplicht fietspad moet de fietser het fietspad gebruiken.', art:'RVV 1990, art. 5 en bijlage 1 bord G11'},
    {t:'mc', v:'Je wilt parkeren in een blauwe zone (bord E10). Wat moet je doen?', o:['Betalen bij de automaat','Een parkeerschijf duidelijk zichtbaar instellen','Niets, parkeren is er gratis en onbeperkt','Je vergunning tonen'], a:1, u:'In een parkeerschijfzone gebruik je een parkeerschijf en blijf je binnen de aangegeven tijd.', art:'RVV 1990, art. 25'}
  ],
  puzzles:[]
},
{
  id:'bijzonder', nr:3, titel:'Bijzondere wegen en manoeuvres', kleur:'--m-bijzonder',
  samenvatting:'Autosnelweg, erf, rotonde, tunnel, spoorwegovergang, in- en uitvoegen, keren en achteruitrijden.',
  lessons:[
    {t:'Wie mag op de autosnelweg', b:'Alleen motorvoertuigen die minimaal 60 km/h kunnen én mogen rijden. Op de autoweg is dat 50 km/h. Fietsers, bromfietsers, landbouwvoertuigen en voetgangers mogen er niet komen.', a:'RVV 1990, art. 42 en bijlage 1 borden G1 en G3'},
    {t:'Keren en achteruitrijden op de snelweg', b:'Op een autosnelweg en autoweg mag je niet keren en niet achteruitrijden. Mis je je afrit, dan rijd je door tot de volgende.', a:'RVV 1990, art. 43'},
    {t:'Invoegen en uitvoegen', b:'Invoegen is een bijzondere manoeuvre: je past je snelheid aan die van de doorgaande rijbaan aan en laat dat verkeer voorgaan. Uitvoegen doe je tijdig, op de uitvoegstrook, niet door hard te remmen op de rijbaan.', a:'RVV 1990, art. 54'},
    {t:'Vluchtstrook en spitsstrook', b:'De vluchtstrook is alleen voor noodgevallen. Een spitsstrook is een vluchtstrook die als rijstrook is opengesteld; dat zie je aan een groene pijl boven de strook. Staat er een rood kruis, dan mag je er niet rijden.', a:'RVV 1990, art. 1, 43 en 70'},
    {t:'Pech op de snelweg', b:'Rijd zo ver mogelijk naar rechts, zet je alarmlichten aan, stap rechts uit, ga achter de vangrail staan en bel het alarmnummer of de wegenwacht. Een gevarendriehoek plaats je niet op de snelweg; op andere wegen wel, zo’n 30 meter voor de auto.', a:'RVV 1990, art. 43 en 58'},
    {t:'Erf', b:'Op een erf mag je niet sneller dan 15 km per uur rijden. Voetgangers mogen de hele breedte gebruiken en spelen is toegestaan. Parkeren mag alleen in de vakken. Een erf verlaten is een bijzondere manoeuvre.', a:'RVV 1990, art. 44, 45, 46 en 54'},
    {t:'Rotonde', b:'Volg de rotonde rechtsom (bord D1). Haaientanden bij de oprit betekenen voorrang verlenen aan het verkeer op de rotonde. Bij het verlaten geef je rechts richting aan en laat je rechtdoorgaande fietsers en voetgangers voorgaan.', a:'RVV 1990, art. 18 en bijlage 1 bord D1'},
    {t:'Tunnel', b:'Doe je dimlicht aan, hou afstand en stem je radio af op de tunnelzender. Bij file in een tunnel: motor uit, alarmlichten aan. Bij brand verlaat je de auto met de sleutel erin en loop je naar de dichtstbijzijnde nooduitgang.', a:'RVV 1990, art. 32 en bijlage 1 bord L13'},
    {t:'Spoorwegovergang', b:'De trein gaat altijd voor. Rijd pas op als je er zeker helemaal voorbij kunt komen. Rode knipperlichten betekenen stoppen, ook als de bomen nog openstaan. Blijf je toch staan op het spoor: rijd door de bomen heen, die breken af.', a:'RVV 1990, art. 14 en 71'},
    {t:'Bijzondere manoeuvres op een rij', b:'Wegrijden, achteruitrijden, keren, een inrit of uitrit in- of uitrijden, van rijstrook wisselen, invoegen, uitvoegen en een erf verlaten. Bij al deze manoeuvres laat je het overige verkeer voorgaan.', a:'RVV 1990, art. 54'},
    {t:'Inhalen van langzaam verkeer', b:'Een fiets of bromfiets haal je in met als vuistregel minstens anderhalve meter zijdelingse afstand. Bij bord F1 mag je motorvoertuigen niet inhalen, maar een fiets wel.', a:'RVV 1990, art. 11 en bijlage 1 bord F1'},
    {t:'Busbaan en busstrook', b:'Bij bord F13 mag je als automobilist niet op de baan of strook rijden. Een busstrook met het woord BUS op het wegdek en een doorgetrokken streep mag je ook niet gebruiken.', a:'RVV 1990, art. 81 en 76'}
  ],
  questions:[
    {t:'mc', v:'Welke minimumsnelheid moet je voertuig kunnen en mogen rijden op de autosnelweg?', o:['40 km/h','50 km/h','60 km/h','80 km/h'], a:2, u:'Op de autosnelweg is dat 60 km/h, op de autoweg 50 km/h.', art:'RVV 1990, art. 42'},
    {t:'jn', v:'Je mag achteruitrijden op een autosnelweg als je je afrit mist.', a:1, u:'Nee. Keren en achteruitrijden zijn op de autosnelweg en autoweg verboden. Rijd door tot de volgende afrit.', art:'RVV 1990, art. 43'},
    {t:'mc', v:'Je voegt in vanaf de invoegstrook. Wat doe je?', o:['Snelheid aanpassen en het doorgaande verkeer voor laten gaan','Afremmen en wachten tot de strook ophoudt','Doorrijden; het verkeer op de rijbaan moet ruimte maken','Alarmlichten aan'], a:0, u:'Invoegen is een bijzondere manoeuvre. Je rijdt mee op snelheid en laat het doorgaande verkeer voorgaan.', art:'RVV 1990, art. 54'},
    {t:'mc', v:'Boven de vluchtstrook brandt een groene pijl. Wat betekent dat?', o:['De vluchtstrook is open als spitsstrook','Alleen hulpdiensten mogen erop','Je moet er juist af','Pechgevallen staan verderop'], a:0, u:'Een groene pijl boven de strook betekent dat de spitsstrook is opengesteld. Een rood kruis betekent gesloten.', art:'RVV 1990, art. 73'},
    {t:'multi', v:'Je krijgt pech op de autosnelweg. Wat doe je?', o:['Zo ver mogelijk naar rechts','Alarmlichten aan','Gevarendriehoek 30 meter achter de auto plaatsen','Rechts uitstappen','Achter de vangrail wachten'], a:[0,1,3,4], u:'Op de autosnelweg plaats je geen gevarendriehoek; dat is te gevaarlijk. Op andere wegen doe je dat wel.', art:'RVV 1990, art. 43 en 58'},
    {t:'mc', v:'Wat is de maximumsnelheid op een erf?', o:['15 km/h (stapvoets)','30 km/h','Er geldt geen limiet','50 km/h'], a:0, u:'Op een erf rijd je stapvoets: maximaal 15 km/h.', art:'RVV 1990, art. 45'},
    {t:'jn', v:'Op een erf mag je overal parkeren waar ruimte is.', a:1, u:'Nee. Op een erf mag je alleen parkeren in de vakken of op plaatsen met de letter P.', art:'RVV 1990, art. 46'},
    {t:'mc', v:'Je verlaat een erf en rijdt de weg op. Wat geldt?', o:['Verkeer van rechts','Je laat al het verkeer voorgaan','Je hebt voorrang','Je moet verplicht stoppen'], a:1, u:'Een erf verlaten is een bijzondere manoeuvre; je laat al het verkeer voorgaan, ook voetgangers.', art:'RVV 1990, art. 54'},
    {t:'mc', v:'Je verlaat een rotonde. Wat geef je aan?', o:['Niets','Links richting','Rechts richting','Alarmlichten'], a:2, u:'Bij het verlaten van de rotonde geef je rechts richting aan. Bij het oprijden geef je normaal gesproken niets aan.', art:'RVV 1990, art. 55'},
    {t:'multi', v:'Wat doe je bij file in een tunnel?', o:['Motor uitzetten','Alarmlichten aan','Afstand houden tot de voorligger','Keren en terugrijden','Radio op de tunnelzender'], a:[0,1,2,4], u:'Keren in een tunnel is levensgevaarlijk en verboden.', art:'WVW 1994, art. 5'},
    {t:'mc', v:'Er is brand in de tunnel en je moet je auto achterlaten. Wat doe je met de sleutel?', o:['Meenemen','In het contact laten','In de kofferbak leggen','Aan de hulpdiensten geven'], a:1, u:'Laat de sleutel in het contact, zodat hulpdiensten de auto kunnen verplaatsen. Loop naar de dichtstbijzijnde nooduitgang.', art:'Tunnelveiligheidsinstructies'},
    {t:'jn', v:'Bij een spoorwegovergang mag je oprijden zodra de bomen omhoog gaan, ook als er file staat.', a:1, u:'Nee. Je rijdt pas op als je er helemaal voorbij kunt komen; anders blijf je op het spoor staan.', art:'RVV 1990, art. 14'},
    {t:'mc', v:'Je staat met je auto stil op een spoorwegovergang en de bomen sluiten. Wat doe je?', o:['Wachten op hulp','Doorrijden; de bomen breken af','Achteruitrijden onder de boom door','Uitstappen en de boom omhoog duwen'], a:1, u:'Rijd door. De bomen zijn gemaakt om af te breken. Blijf nooit op het spoor staan.', art:'RVV 1990, art. 71'},
    {t:'mc', v:'Met hoeveel zijdelingse afstand haal je een fietser in?', o:['Een halve meter','Anderhalve meter','Drie meter','Maakt niet uit'], a:1, u:'Hou als vuistregel minstens anderhalve meter aan, zodat een slingerende fietser niet in gevaar komt. Het is geen wettelijk vastgelegd getal, maar wel de norm waarop je wordt afgerekend als het misgaat.', art:'WVW 1994, art. 5 en RVV 1990, art. 11'},
    {t:'jn', v:'Bij bord F1 (inhaalverbod voor motorvoertuigen) mag je wel een fietser inhalen.', a:0, u:'Ja. Het verbod geldt alleen voor het onderling inhalen van motorvoertuigen.', art:'RVV 1990, bijlage 1 bord F1'},
    {t:'multi', v:'Welke van deze zijn bijzondere manoeuvres?', o:['Uitvoegen','Een inrit inrijden','Rechtdoor rijden op een rotonde','Keren','Wegrijden vanaf de parkeerplaats'], a:[0,1,3,4], u:'Rechtdoor rijden op een rotonde is geen bijzondere manoeuvre.', art:'RVV 1990, art. 54'},
    {t:'mc', v:'Je rijdt op een busstrook met een doorgetrokken streep en het woord BUS. Wat geldt?', o:['Je mag er altijd rijden','Je mag er niet rijden','Alleen in de spits','Alleen om rechtsaf te slaan'], a:1, u:'Een busbaan of busstrook is alleen voor lijnbussen. De doorgetrokken streep mag je bovendien niet overschrijden.', art:'RVV 1990, art. 81 en 76'},
    {t:'mc', v:'Je nadert een rotonde met haaientanden en bord B6. Op de rotonde rijdt een auto. Wat doe je?', o:['Doorrijden, je komt van rechts','Voorrang verlenen aan de auto op de rotonde','Stoppen en wachten tot de rotonde leeg is','Claxonneren'], a:1, u:'De haaientanden wijzen naar jou: voorrang verlenen aan het verkeer dat al op de rotonde rijdt.', art:'RVV 1990, art. 80'},
    {t:'jn', v:'Een bromfietser mag op een autoweg rijden.', a:1, u:'Nee. Een bromfiets kan en mag geen 50 km/h rijden en hoort dus niet op de autoweg.', art:'RVV 1990, art. 42'},
    {t:'mc', v:'Je wilt keren op een smalle weg buiten de bebouwde kom. Wat geldt?', o:['Je hebt voorrang want je staat stil','Keren is een bijzondere manoeuvre; al het verkeer gaat voor','Verkeer van rechts','Je moet alarmlichten aanzetten en dan mag het'], a:1, u:'Keren is een bijzondere manoeuvre. Doe het op een overzichtelijke plek en laat iedereen voorgaan.', art:'RVV 1990, art. 54'},
    {t:'mc', v:'Je nadert een uitvoegstrook maar zit nog op de linkerrijstrook. Wat doe je?', o:['Hard remmen en schuin oversteken','Doorrijden naar de volgende afrit','Alarmlichten aan en toch uitvoegen','Over de doorgetrokken streep gaan'], a:1, u:'Te laat uitvoegen veroorzaakt ongelukken. Rijd door naar de volgende afrit en keer pas buiten de snelweg; keren op de snelweg zelf mag niet.', art:'WVW 1994, art. 5 en RVV 1990, art. 43'},
    {t:'fill', v:'Hoeveel meter voor je auto plaats je een gevarendriehoek op een gewone weg buiten de bebouwde kom? (alleen het getal)', a:'30', u:'Ongeveer 30 meter, zodat anderen op tijd gewaarschuwd zijn. Op de autosnelweg plaats je geen driehoek.', art:'RVV 1990, art. 58'},
    {t:'jn', v:'Boven jouw rijstrook staat een rood kruis. Je mag er langzaam doorrijden.', a:1, u:'Nee. Een rood kruis betekent dat de rijstrook gesloten is; je verlaat hem tijdig en veilig.', art:'RVV 1990, art. 73'},
    {t:'mc', v:'Op een erf speelt een kind op straat. Wat geldt?', o:['Het kind moet opzij gaan','Voetgangers mogen de hele breedte van de weg gebruiken','Alleen op het trottoir mag gespeeld worden','Je mag claxonneren om door te kunnen'], a:1, u:'Op een erf mogen voetgangers de volle breedte gebruiken; jij past je aan en rijdt stapvoets.', art:'RVV 1990, art. 44'},
    {t:'mc', v:'Welke voertuigen mogen niet op de autosnelweg?', o:['Motoren','Vrachtauto’s','Landbouwvoertuigen','Auto’s met aanhanger'], a:2, u:'Landbouwvoertuigen halen de vereiste 60 km/h niet. Motoren, vrachtauto’s en auto’s met aanhanger mogen er wel.', art:'RVV 1990, art. 42'},
    {t:'jn', v:'Op een rotonde rijd je linksom als dat korter is.', a:1, u:'Nee. Bord D1 schrijft de rijrichting voor: je volgt de rotonde rechtsom.', art:'RVV 1990, bijlage 1 bord D1'}
  ],
  puzzles:[
    {v:'Jij nadert een rotonde uit het zuiden en wilt de eerste afslag rechts nemen. Fietser F rijdt rechtdoor over het fietspad langs die afslag. Klik de volgorde.', scene:{type:'kruis', borden:'haaientanden-zuid', actors:[{id:'A',van:'zuid',naar:'rechts',label:'Jij',kleur:'jij'},{id:'F',van:'oost',naar:'rd',label:'F',soort:'fiets'}]}, a:['F','A'], u:'De rotonde verlaten is afslaan. De rechtdoorgaande fietser gaat voor.', art:'RVV 1990, art. 18 lid 1'},
    {v:'Jij staat op de invoegstrook (zuid). Op de doorgaande rijbaan nadert auto B. Klik de volgorde.', scene:{type:'kruis', borden:'geen', actors:[{id:'A',van:'zuid',naar:'rd',label:'Jij',kleur:'jij'},{id:'B',van:'west',naar:'rd',label:'B'}]}, a:['B','A'], u:'Invoegen is een bijzondere manoeuvre: het verkeer op de doorgaande rijbaan gaat voor.', art:'RVV 1990, art. 54'},
    {v:'Je rijdt een erf uit (zuid). Op de weg nadert auto B en op het trottoir loopt voetganger V. Klik de volgorde.', scene:{type:'uitrit', actors:[{id:'A',van:'uitrit',naar:'rd',label:'Jij',kleur:'jij'},{id:'B',van:'west',naar:'rd',label:'B'},{id:'V',van:'trottoir',naar:'rd',label:'V',soort:'voet'}]}, a:['V','B','A'], u:'Een erf verlaten is een bijzondere manoeuvre: iedereen gaat voor, ook de voetganger die je uitrit kruist.', art:'RVV 1990, art. 54'}
  ]
},
{
  id:'veilig', nr:4, titel:'Veilig rijden en noodsituaties', kleur:'--m-veilig',
  samenvatting:'Stopafstand, remmen, slippen, zicht, vermoeidheid en wat je doet bij een ongeval.',
  lessons:[
    {t:'Stopafstand = reactieafstand + remweg', b:'De reactieafstand is wat je aflegt voordat je remt, ongeveer een seconde. De remweg is wat je daarna nog aflegt. Samen is dat je stopafstand.', a:'RVV 1990, art. 19'},
    {t:'Twee keer zo hard is vier keer zo lange remweg', b:'De remweg neemt toe met het kwadraat van de snelheid. Van 50 naar 100 km/h is de remweg dus ongeveer vier keer zo lang, niet twee keer.', a:'RVV 1990, art. 19'},
    {t:'Op een natte weg', b:'Bij regen is de remweg ongeveer anderhalf tot twee keer zo lang. Bij ijzel kan dat oplopen tot tien keer. Hou daarom drie seconden afstand in plaats van twee.', a:'RVV 1990, art. 19'},
    {t:'Aquaplaning', b:'Bij een laag profiel en veel water kan er een laagje water tussen band en wegdek komen. Je verliest dan grip. Niet sturen of remmen: gas los en de auto maakt vanzelf weer contact.', a:'Rijtechniek'},
    {t:'Slippen', b:'Onderstuur betekent dat de voorkant rechtdoor schuift: gas los en stuur minder in. Overstuur betekent dat de achterkant uitbreekt: stuur rustig tegen, in de richting waar je heen wilt.', a:'Rijtechniek'},
    {t:'ABS gebruiken', b:'Met ABS blokkeren de wielen niet, zodat je kunt blijven sturen tijdens een noodstop. Trap het rempedaal stevig in en hou het ingetrapt; het trillen van het pedaal is normaal.', a:'Regeling voertuigen'},
    {t:'Dode hoek', b:'Rechts naast en schuin achter je zit een gebied dat je in je spiegels niet ziet. Kijk daarom altijd over je schouder voordat je van rijstrook wisselt of rechtsaf slaat. Bij een vrachtwagen is de dode hoek veel groter.', a:'WVW 1994, art. 5 en RVV 1990, art. 54'},
    {t:'Vermoeidheid', b:'Vermoeid rijden lijkt in reactietijd op rijden onder invloed. Stop elke twee uur, loop even, en neem bij slaperigheid een korte pauze. Koffie of raam open helpt maar kort.', a:'WVW 1994, art. 5'},
    {t:'Bij een ongeval', b:'Zet je auto veilig neer, alarmlichten aan, hesje aan. Bel 112 bij gewonden. Je mag nooit doorrijden na een ongeval; dat is een misdrijf. Wissel gegevens uit en vul een schadeformulier in.', a:'WVW 1994, art. 7'},
    {t:'Hulp verlenen', b:'Zorg eerst voor je eigen veiligheid, dan die van anderen. Haal een gewonde alleen uit de auto bij acuut gevaar, zoals brand. Een helm van een motorrijder laat je af, tenzij de ademhaling in gevaar is.', a:'WVW 1994, art. 7'},
    {t:'Gevaar op de weg', b:'Je mag geen gevaar veroorzaken of het verkeer hinderen. Dat is een ruime regel waaronder ook te dicht op de voorligger rijden en onnodig links rijden vallen.', a:'WVW 1994, art. 5'},
    {t:'Rijden onder invloed', b:'De grens is 0,5 promille, voor een beginnend bestuurder 0,2 promille. Ook medicijnen met een gele sticker en drugs vallen hieronder. Alcohol vertraagt je reactie en maakt je overmoedig.', a:'WVW 1994, art. 8'}
  ],
  questions:[
    {t:'mc', v:'Waaruit bestaat de stopafstand?', o:['Alleen de remweg','Reactieafstand plus remweg','Remweg plus veiligheidsmarge','Reactietijd plus snelheid'], a:1, u:'De stopafstand is de reactieafstand (voor je remt) plus de remweg (terwijl je remt).', art:'Rijtechnisch gegeven'},
    {t:'mc', v:'Je verdubbelt je snelheid van 50 naar 100 km/h. Wat gebeurt er met je remweg?', o:['Hij wordt twee keer zo lang','Hij wordt ongeveer vier keer zo lang','Hij blijft gelijk','Hij wordt anderhalf keer zo lang'], a:1, u:'De remweg neemt toe met het kwadraat van de snelheid: twee keer zo hard is ongeveer vier keer zo lange remweg.', art:'Rijtechnisch gegeven'},
    {t:'jn', v:'Bij regen hou je drie seconden afstand in plaats van twee.', a:0, u:'Ja. Bij nat wegdek is je remweg veel langer, dus vergroot je je afstand.', art:'RVV 1990, art. 19'},
    {t:'mc', v:'Je krijgt aquaplaning. Wat doe je?', o:['Hard remmen','Gas los en stuur recht houden','Snel bijsturen','Handrem gebruiken'], a:1, u:'Remmen of sturen heeft geen effect zolang de banden geen contact maken. Gas los, stuur recht, wacht tot de grip terug is.', art:'Rijtechnisch gegeven'},
    {t:'mc', v:'De achterkant van je auto breekt uit in een bocht. Wat doe je?', o:['Hard remmen','Tegensturen in de richting waar je heen wilt','Harder gas geven','Handrem aantrekken'], a:1, u:'Bij overstuur stuur je rustig tegen, de kant op waar je heen wilt, en neem je gas terug.', art:'Rijtechnisch gegeven'},
    {t:'jn', v:'Met ABS moet je tijdens een noodstop het rempedaal pompend bedienen.', a:1, u:'Nee. Met ABS trap je het pedaal stevig in en hou je het ingetrapt. Het systeem doet het pompen voor je.', art:'Regeling voertuigen'},
    {t:'mc', v:'Wat is het grote voordeel van ABS?', o:['Kortere remweg op elk wegdek','Je kunt blijven sturen tijdens hard remmen','De auto remt automatisch','De banden slijten minder'], a:1, u:'ABS voorkomt blokkeren, zodat je kunt blijven sturen. Op los grind kan de remweg zelfs iets langer zijn.', art:'Regeling voertuigen'},
    {t:'mc', v:'Je wilt rechtsaf slaan. Waar let je extra op?', o:['De tegenligger','De dode hoek rechts naast en achter je','Het verkeer van links','De snelheidsmeter'], a:1, u:'In de dode hoek rechts kan een fietser of bromfietser zitten. Kijk over je schouder voordat je stuurt.', art:'WVW 1994, art. 5'},
    {t:'multi', v:'Wat doe je als eerste bij een ongeval met gewonden?', o:['Zorgen voor je eigen veiligheid','112 bellen','Gewonden altijd uit de auto halen','Alarmlichten aan en hesje aan','Doorrijden en later melden'], a:[0,1,3], u:'Een gewonde verplaats je alleen bij acuut gevaar. Doorrijden na een ongeval is een misdrijf.', art:'WVW 1994, art. 7'},
    {t:'jn', v:'Je mag doorrijden na een aanrijding met alleen blikschade als je later belt.', a:1, u:'Nee. Doorrijden na een ongeval is strafbaar. Je moet ter plaatse je gegevens achterlaten of uitwisselen.', art:'WVW 1994, art. 7'},
    {t:'mc', v:'Wat is de alcoholgrens voor een beginnend bestuurder?', o:['0,0 promille','0,2 promille','0,5 promille','0,8 promille'], a:1, u:'Voor een beginnend bestuurder geldt 0,2 promille (88 microgram per liter uitgeademde lucht). Voor ervaren bestuurders 0,5.', art:'WVW 1994, art. 8'},
    {t:'mc', v:'Je bent erg moe tijdens een lange rit. Wat helpt echt?', o:['Raam open','Koffie','Harde muziek','Stoppen en even rusten'], a:3, u:'Alleen rust helpt. De rest werkt hooguit een paar minuten en geeft een vals gevoel van alertheid.', art:'WVW 1994, art. 5'},
    {t:'jn', v:'Een medicijn met een gele waarschuwingssticker kan je rijvaardigheid beïnvloeden.', a:0, u:'Ja. Een gele sticker betekent dat het middel je rijvaardigheid kan beïnvloeden; lees de bijsluiter en overleg met je arts.', art:'WVW 1994, art. 8'},
    {t:'mc', v:'Je nadert een plek waar een vrachtwagen rechtsaf wil slaan en jij fietst ernaast. Wat is het risico?', o:['De vrachtwagen remt te laat','Je zit in de dode hoek','De vrachtwagen rijdt te hard','Er is geen risico'], a:1, u:'Vrachtwagens hebben een grote dode hoek rechts. Blijf achter de vrachtwagen of maak oogcontact met de chauffeur.', art:'WVW 1994, art. 5'},
    {t:'fill', v:'Hoeveel seconden is de reactietijd van een oplettende bestuurder ongeveer? (cijfer of woord)', a:'een', u:'Ongeveer één seconde. Bij afleiding of vermoeidheid loopt dat flink op.', art:'Rijtechnisch gegeven'},
    {t:'mc', v:'Wat is onderstuur?', o:['De achterkant breekt uit','De voorkant schuift rechtdoor','De auto kantelt','De motor slaat af'], a:1, u:'Bij onderstuur verliezen de voorwielen grip en schuift de auto rechtuit. Gas los en minder insturen.', art:'Rijtechnisch gegeven'},
    {t:'multi', v:'Wat vergroot je remweg?', o:['Nat wegdek','Versleten banden','Een zware lading','Nieuwe remblokken','Een helling naar beneden'], a:[0,1,2,4], u:'Goede remblokken verkorten je remweg juist.', art:'Regeling voertuigen en RVV 1990, art. 19'},
    {t:'mc', v:'Je rijdt in dichte mist en het zicht is minder dan 50 meter. Wat geldt?', o:['Groot licht aanzetten','Dimlicht voeren, snelheid sterk minderen en mistlicht achter mag aan','Alarmlichten aan en doorrijden','Mistlicht achter is verboden'], a:1, u:'Bij zicht onder de 50 meter mag je mistlicht achter voeren. Groot licht werkt averechts in mist. Pas je snelheid aan tot je binnen je zichtafstand kunt stoppen.', art:'RVV 1990, art. 34 lid 2'},
    {t:'jn', v:'Bij mist zet je je groot licht aan om beter te zien.', a:1, u:'Nee. Groot licht weerkaatst in de mist en verblindt je juist. Gebruik dimlicht en zo nodig mistlicht.', art:'RVV 1990, art. 32 en 34'},
    {t:'mc', v:'Je ziet in je spiegel een ambulance met zwaailicht en sirene naderen op de snelweg. Wat doe je?', o:['Hard remmen','Rustig naar rechts en ruimte maken','Op de vluchtstrook gaan staan','Je snelheid verhogen'], a:1, u:'Maak voorspelbaar ruimte zonder bruusk te remmen. Bij file wordt geadviseerd samen een doorgang in het midden vrij te maken; dat is een advies, geen wettelijke regel.', art:'RVV 1990, art. 50'},
    {t:'mc', v:'Welke lichten zet je aan als je stilstaat na een ongeval?', o:['Groot licht','Alarmlichten','Mistlicht voor','Alleen stadslicht'], a:1, u:'Alarmlichten waarschuwen het naderende verkeer dat er iets aan de hand is.', art:'RVV 1990, art. 58'},
    {t:'jn', v:'Je moet een motorhelm altijd afhouden bij een gewonde motorrijder.', a:1, u:'Nee. In principe laat je de helm zitten, tenzij de ademhaling in gevaar is. Wacht op de hulpdiensten.', art:'WVW 1994, art. 7'},
    {t:'mc', v:'Wat betekent het als je rempedaal trilt tijdens een noodstop?', o:['De remmen zijn kapot','Het ABS werkt','Je remt te zacht','Je moet pompen'], a:1, u:'Het trillen hoort bij een werkend ABS. Blijf het pedaal ingetrapt houden en stuur om het obstakel heen.', art:'Regeling voertuigen'},
    {t:'mc', v:'Hoeveel langer kan je remweg zijn op ijzel?', o:['Twee keer','Vier keer','Tot wel tien keer','Nauwelijks langer'], a:2, u:'Op ijzel kan de remweg tot ongeveer tien keer zo lang worden. Rij dan veel langzamer en hou extra afstand.', art:'RVV 1990, art. 19'},
    {t:'jn', v:'Je bent verplicht een veiligheidshesje in de auto te hebben in Nederland.', a:1, u:'Nee, in Nederland is dat niet wettelijk verplicht, maar het is wel sterk aan te raden. In veel andere landen is het wel verplicht.', art:'Geen wettelijke verplichting in Nederland'},
    {t:'mc', v:'Je voelt dat je in slaap dreigt te vallen. Wat is de juiste actie?', o:['Doorrijden tot je bestemming','Bij de eerste veilige gelegenheid stoppen en rusten','Harder gaan rijden om er sneller te zijn','Je raam opendoen en doorrijden'], a:1, u:'Een microslaap van enkele seconden kost op 100 km/h al bijna 100 meter blind rijden. Stop en rust.', art:'WVW 1994, art. 5'}
  ],
  puzzles:[]
},
{
  id:'milieu', nr:6, titel:'Verantwoord en milieubewust rijden', kleur:'--m-milieu',
  samenvatting:'Zuinig rijden, bandenspanning, milieuzones, alcohol en drugs, afleiding en agressie.',
  lessons:[
    {t:'Het Nieuwe Rijden', b:'Schakel vroeg op, rijd gelijkmatig, kijk ver vooruit en laat de auto zoveel mogelijk uitrollen. Zo bespaar je brandstof en rijd je ook veiliger.', a:'Milieubeleid rijksoverheid'},
    {t:'Vroeg opschakelen', b:'Bij een benzinemotor schakel je rond 2.000 tot 2.500 toeren op, bij een diesel rond 2.000. Hoge toeren verbruiken veel meer dan nodig.', a:'Het Nieuwe Rijden'},
    {t:'Motor uit bij stilstand', b:'Sta je langer dan ongeveer een minuut stil, bijvoorbeeld voor een brug of in een file, zet dan de motor uit. Start-stopsystemen doen dit automatisch.', a:'Het Nieuwe Rijden'},
    {t:'Bandenspanning', b:'Te lage bandenspanning kost brandstof, verslechtert je wegligging en versnelt slijtage. Controleer de spanning elke twee maanden bij koude banden en gebruik de waarde uit het instructieboekje.', a:'Regeling voertuigen'},
    {t:'Gewicht en luchtweerstand', b:'Een dakkoffer of fietsendrager kost al snel tien tot twintig procent extra brandstof. Haal hem eraf als je hem niet gebruikt en laat geen onnodige spullen in de auto liggen.', a:'Het Nieuwe Rijden'},
    {t:'Airco en elektrische verbruikers', b:'Airco, stoelverwarming en achterruitverwarming kosten brandstof. Gebruik ze als het nodig is en zet ze daarna weer uit.', a:'Het Nieuwe Rijden'},
    {t:'Milieuzone', b:'In een milieuzone mogen vervuilende voertuigen niet komen; dat is bord C22a. Een nul-emissiezone heeft bord C22c en geldt voor bedrijfs- en vrachtauto\u2019s. Het onderbord zegt steeds welke voertuigen geweerd worden.', a:'RVV 1990, art. 86d en 86e'},
    {t:'Alcohol', b:'De grens is 0,5 promille, voor een beginnend bestuurder 0,2 promille. Alcohol wordt maar langzaam afgebroken, ongeveer één standaardglas per uur. Koffie, douchen of eten versnelt dat niet.', a:'WVW 1994, art. 8'},
    {t:'Drugs en medicijnen', b:'Voor drugs gelden aparte grenswaarden en er wordt op straat op getest (WVW 1994, art. 8). Medicijnen met een gele sticker kunnen je rijvaardigheid beïnvloeden; die sticker komt uit de indeling van apothekersorganisatie KNMP.', a:'WVW 1994, art. 8'},
    {t:'Afleiding', b:'Een telefoon vasthouden mag niet. Ook navigatie instellen, eten of een gesprek over je schouder kost aandacht. Zet alles klaar voordat je wegrijdt.', a:'RVV 1990, art. 61a'},
    {t:'Agressie in het verkeer', b:'Boos reageren maakt een situatie alleen gevaarlijker. Laat je niet opjagen, hou afstand en maak geen oogcontact met iemand die uitdaagt.', a:'WVW 1994, art. 5'},
    {t:'Zuinig en veilig gaan samen', b:'Ver vooruitkijken, vloeiend rijden en op tijd gas loslaten scheelt brandstof én voorkomt hard remmen. De zuinige rijstijl is ook de rustige rijstijl.', a:'Het Nieuwe Rijden'}
  ],
  questions:[
    {t:'mc', v:'Bij welk toerental schakel je een benzineauto ongeveer op volgens Het Nieuwe Rijden?', o:['1.000 toeren','2.000 tot 2.500 toeren','3.500 toeren','4.000 toeren'], a:1, u:'Rond 2.000 tot 2.500 toeren opschakelen bespaart brandstof zonder dat de motor te zwaar belast wordt.', art:'Het Nieuwe Rijden'},
    {t:'jn', v:'Te lage bandenspanning verhoogt je brandstofverbruik.', a:0, u:'Ja. Lage spanning geeft meer rolweerstand, dus meer verbruik, en bovendien slechtere wegligging en snellere slijtage.', art:'Regeling voertuigen'},
    {t:'mc', v:'Je staat twee minuten stil voor een open brug. Wat is het zuinigst?', o:['Motor laten draaien','Motor uitzetten','In zijn vrij laten draaien','Gas bijgeven'], a:1, u:'Sta je langer dan ongeveer een minuut stil, zet de motor dan uit.', art:'Het Nieuwe Rijden'},
    {t:'mc', v:'Hoeveel extra brandstof kost een dakkoffer ongeveer?', o:['Niets','Ongeveer 1 procent','Tien tot twintig procent','Meer dan de helft'], a:2, u:'De extra luchtweerstand kost al snel tien tot twintig procent. Haal de koffer eraf als je hem niet gebruikt.', art:'Het Nieuwe Rijden'},
    {t:'mc', v:'Wat betekent bord C22a?', o:['Parkeerzone','Milieuzone','Einde bebouwde kom','Voetgangersgebied'], a:1, u:'C22a geeft een milieuzone aan. Het onderbord zegt welke voertuigen geweerd worden. De nul-emissiezone heeft een eigen bord: C22c.', art:'RVV 1990, art. 86d'},
    {t:'mc', v:'Hoeveel alcohol breekt je lichaam ongeveer per uur af?', o:['Eén standaardglas','Drie glazen','Een halve fles wijn','Dat hangt af van hoeveel je eet'], a:0, u:'Ongeveer één standaardglas per uur. Koffie, eten of een douche versnelt de afbraak niet.', art:'WVW 1994, art. 8'},
    {t:'jn', v:'Een kop koffie maakt je weer nuchter genoeg om te rijden.', a:1, u:'Nee. Koffie maakt je hooguit wakkerder, maar verlaagt je alcoholpromillage niet.', art:'WVW 1994, art. 8'},
    {t:'multi', v:'Wat hoort bij zuinig rijden?', o:['Vroeg opschakelen','Ver vooruitkijken','Vaak hard optrekken en remmen','De auto laten uitrollen','Bandenspanning op peil houden'], a:[0,1,3,4], u:'Hard optrekken en remmen is juist de duurste en gevaarlijkste rijstijl.', art:'Het Nieuwe Rijden'},
    {t:'mc', v:'Hoe vaak controleer je idealiter je bandenspanning?', o:['Elke week','Elke twee maanden','Eén keer per jaar','Alleen bij de APK'], a:1, u:'Ongeveer elke twee maanden, bij koude banden, met de waarde uit het instructieboekje of op de tankklep.', art:'Advies van de RDW en de bandenbranche'},
    {t:'jn', v:'Je mag je telefoon vasthouden om de route in te stellen als je langzaam rijdt.', a:1, u:'Nee. Een mobiel elektronisch apparaat vasthouden mag niet tijdens het rijden. Stel je navigatie in voordat je wegrijdt.', art:'RVV 1990, art. 61a'},
    {t:'mc', v:'Iemand rijdt agressief vlak achter je en knippert met de lichten. Wat doe je?', o:['Harder rijden','Remmen om een les te leren','Rustig blijven en bij gelegenheid ruimte maken','Oogcontact maken en gebaren'], a:2, u:'Laat je niet opjagen en ga de confrontatie niet aan. Maak op een veilig moment ruimte zodat de ander voorbij kan.', art:'WVW 1994, art. 5'},
    {t:'mc', v:'Wat is de alcoholgrens voor een ervaren bestuurder?', o:['0,2 promille','0,5 promille','0,8 promille','1,0 promille'], a:1, u:'0,5 promille, oftewel 220 microgram alcohol per liter uitgeademde lucht. Voor beginnende bestuurders 0,2.', art:'WVW 1994, art. 8'},
    {t:'jn', v:'Airco gebruiken kost extra brandstof.', a:0, u:'Ja. Airco belast de motor. Gebruik hem als het nodig is en zet hem daarna uit.', art:'Het Nieuwe Rijden'},
    {t:'mc', v:'Wat is het effect van een lagere snelheid op de snelweg op je verbruik?', o:['Geen effect','Het verbruik daalt flink door minder luchtweerstand','Het verbruik stijgt','Alleen bij een diesel'], a:1, u:'Luchtweerstand neemt sterk toe met de snelheid. 100 rijden in plaats van 130 scheelt aanzienlijk.', art:'Het Nieuwe Rijden'},
    {t:'fill', v:'Welke kleur sticker op een medicijnverpakking waarschuwt dat het je rijvaardigheid kan beïnvloeden? (één woord)', a:'geel', u:'Een gele sticker betekent dat het middel de rijvaardigheid kan beïnvloeden. Lees altijd de bijsluiter.', art:'KNMP-indeling rijvaardigheid'},
    {t:'multi', v:'Wat vergroot de kans op afleiding?', o:['Navigatie instellen tijdens het rijden','Eten achter het stuur','Je route vooraf bekijken','Een gesprek met passagiers achterin','Telefoon in je hand'], a:[0,1,3,4], u:'Je route vooraf bekijken vermindert afleiding juist.', art:'RVV 1990, art. 61a en WVW 1994, art. 5'},
    {t:'mc', v:'Je rijdt een nul-emissiezone binnen met een dieselbestelbus. Wat kan er gebeuren?', o:['Niets','Je krijgt een boete als je voertuig niet is toegestaan','Je mag er maximaal 30 km/h','Je moet je motor uitzetten'], a:1, u:'De nul-emissiezone (bord C22c) geldt voor bedrijfs- en vrachtauto’s. Camera’s controleren het kenteken. Voor diesel personenauto’s geldt de gewone milieuzone, bord C22a.', art:'RVV 1990, art. 86e'},
    {t:'jn', v:'Start-stop zet de motor automatisch uit als je stilstaat.', a:0, u:'Ja. Dat bespaart brandstof in de stad en bij files. Het systeem start de motor weer bij het loslaten van de rem of koppeling.', art:'Het Nieuwe Rijden'},
    {t:'mc', v:'Wat is het zuinigst bij het naderen van een rood stoplicht?', o:['Doorrijden en kort hard remmen','Gas loslaten en laten uitrollen','In een lage versnelling blijven gas geven','Afwisselend gas en rem'], a:1, u:'Uitrollen gebruikt nauwelijks brandstof en voorkomt onnodig remmen. Kijk ver vooruit.', art:'Het Nieuwe Rijden'},
    {t:'mc', v:'Je hebt gisteravond veel gedronken en rijdt de volgende ochtend. Wat geldt?', o:['Na een nacht slapen ben je altijd nuchter','Je kunt nog boven de grens zitten','Alleen bij sterke drank blijft het hangen','Alcohol is na zes uur altijd weg'], a:1, u:'Je lichaam breekt ongeveer één glas per uur af. Na een zware avond zit je ’s ochtends nog makkelijk boven de grens.', art:'WVW 1994, art. 8'}
  ],
  puzzles:[]
},
{
  id:'wet', nr:7, titel:'Wetgeving', kleur:'--m-wet',
  samenvatting:'Rijbewijs, beginnend bestuurder, APK, verzekering, documenten, lading en aansprakelijkheid.',
  lessons:[
    {t:'Rijbewijs B', b:'Je mag vanaf je 18e zelfstandig rijden met een rijbewijs B. Met 2toDrive kun je vanaf 16,5 jaar theorie doen, vanaf 17 je examen halen en tot je 18e alleen rijden met een coach.', a:'Reglement rijbewijzen'},
    {t:'Geldigheid', b:'Het theoriecertificaat is anderhalf jaar geldig. Een rijbewijs is in principe tien jaar geldig; vanaf 70 jaar wordt die termijn korter en gelden extra keuringen.', a:'Reglement rijbewijzen en WVW 1994, art. 122'},
    {t:'Beginnend bestuurder', b:'Je bent beginnend bestuurder gedurende vijf jaar na het halen van je eerste rijbewijs, en zeven jaar als je via 2toDrive begonnen bent. Je alcohollimiet is dan 0,2 promille en bij herhaalde zware overtredingen volgt een onderzoek naar je rijvaardigheid.', a:'WVW 1994, art. 8 lid 3 en art. 130 t/m 134'},
    {t:'Wat moet je bij je hebben', b:'Op vordering van de politie moet je je rijbewijs \u00e9n je kentekenbewijs kunnen overhandigen. Neem de kentekencard dus mee. In het buitenland komen daar vaak de groene kaart en soms een internationaal rijbewijs bij.', a:'WVW 1994, art. 160'},
    {t:'APK', b:'Een personenauto op benzine die jonger is dan vier jaar hoeft nog niet gekeurd. Daarna geldt kort gezegd: na vier jaar de eerste keuring, dan om de twee jaar en vanaf acht jaar oud jaarlijks. Diesel en LPG moeten eerder en vaker.', a:'Regeling voertuigen'},
    {t:'Verzekering', b:'Een WA-verzekering is verplicht voor elk motorvoertuig met kenteken, ook als het stilstaat. Zonder verzekering krijg je automatisch een boete via de RDW.', a:'Wet aansprakelijkheidsverzekering motorrijtuigen'},
    {t:'Massa’s en passagiers', b:'Met rijbewijs B rijd je een auto met een toegestane maximummassa tot 3.500 kg en maximaal acht passagiers naast de bestuurder. Voor een zwaardere combinatie heb je code 96 of rijbewijs BE nodig.', a:'Reglement rijbewijzen'},
    {t:'Lading', b:'Lading moet goed vastzitten en mag het zicht en de verlichting niet belemmeren. Achter de auto mag lading maximaal één meter uitsteken, met een markeringsbord. Aan de voorkant mag alleen ondeelbare lading uitsteken, ook hooguit één meter.', a:'Regeling voertuigen, art. 5.18.12 en 5.18.13'},
    {t:'Gevaarlijke overtredingen', b:'Artikel 5 WVW verbiedt gevaar of hinder veroorzaken. Artikel 6 gaat over een ongeval met letsel of de dood door schuld. Artikel 7 verbiedt doorrijden na een ongeval. Artikel 8 gaat over rijden onder invloed.', a:'WVW 1994, art. 5 t/m 8'},
    {t:'Ontzegging van de rijbevoegdheid', b:'Een rechter kan je rijbevoegdheid ontzeggen. Rijd je toch, dan is dat een misdrijf. Bij zware overtredingen kan je rijbewijs ook direct ingevorderd worden.', a:'WVW 1994, art. 9 en 164'},
    {t:'Aanhangwagen', b:'Met rijbewijs B mag je een aanhanger trekken als de combinatie niet zwaarder is dan 3.500 kg. Met code 96 mag dat tot 4.250 kg, met rijbewijs BE tot 7.000 kg.', a:'Reglement rijbewijzen'},
    {t:'Kenteken en RDW', b:'Elk motorvoertuig heeft een kenteken dat bij de RDW geregistreerd staat. Verkoop je je auto, dan zorg je voor overschrijving en een vrijwaringsbewijs; anders blijf je aansprakelijk voor boetes en belasting.', a:'WVW 1994, art. 36, 50 en 51a'}
  ],
  questions:[
    {t:'mc', v:'Hoelang is je theoriecertificaat geldig?', o:['Zes maanden','Eén jaar','Anderhalf jaar','Vijf jaar'], a:2, u:'Anderhalf jaar. Daarna moet je opnieuw theorie-examen doen.', art:'Reglement rijbewijzen'},
    {t:'mc', v:'Hoelang ben je beginnend bestuurder als je op je 18e je rijbewijs haalt?', o:['Drie jaar','Vijf jaar','Zeven jaar','Tot je 25e'], a:1, u:'Vijf jaar. Als je via 2toDrive bent begonnen, is dat zeven jaar.', art:'WVW 1994, art. 8 lid 3 en Reglement rijbewijzen'},
    {t:'jn', v:'Een WA-verzekering is ook verplicht als je auto alleen maar stilstaat op de oprit.', a:0, u:'Ja. Zolang het voertuig een kenteken op jouw naam heeft en niet geschorst is, is WA verplicht.', art:'Wet aansprakelijkheidsverzekering motorrijtuigen'},
    {t:'mc', v:'Wat is de maximale toegestane massa van een auto die je met rijbewijs B mag besturen?', o:['2.500 kg','3.500 kg','5.000 kg','7.500 kg'], a:1, u:'3.500 kg toegestane maximummassa, met maximaal acht passagiers naast de bestuurder.', art:'Reglement rijbewijzen'},
    {t:'mc', v:'Hoeveel mag lading maximaal achter je auto uitsteken?', o:['Een halve meter','Eén meter','Twee meter','Zoveel je wilt als het vastzit'], a:1, u:'Maximaal één meter, en dan moet er een rood-wit markeringsbord aan. Aan de voorkant mag lading niet uitsteken.', art:'Regeling voertuigen, art. 5.18.12'},
    {t:'jn', v:'Je moet je kentekenbewijs (de kentekencard) kunnen tonen als de politie erom vraagt.', a:0, u:'Ja. Op vordering van de politie moet je zowel je rijbewijs als je kentekenbewijs overhandigen. De kentekencard hoort dus in de auto of bij je te zijn.', art:'WVW 1994, art. 160'},
    {t:'mc', v:'Wat is de alcoholgrens voor een beginnend bestuurder?', o:['0,0 promille','0,2 promille','0,5 promille','0,8 promille'], a:1, u:'0,2 promille, oftewel 88 microgram per liter uitgeademde lucht.', art:'WVW 1994, art. 8'},
    {t:'mc', v:'Welk wetsartikel verbiedt doorrijden na een ongeval?', o:['Artikel 5 WVW','Artikel 6 WVW','Artikel 7 WVW','Artikel 8 WVW'], a:2, u:'Artikel 7 WVW verbiedt het verlaten van de plaats van een ongeval zonder je gegevens achter te laten.', art:'WVW 1994, art. 7'},
    {t:'multi', v:'Welke van deze zijn verplicht voor een auto op de openbare weg?', o:['Geldige APK','WA-verzekering','Geldig kenteken','Veiligheidshesje','Brandblusser'], a:[0,1,2], u:'Een hesje en een brandblusser zijn in Nederland aan te raden maar niet verplicht.', art:'WVW 1994 en Regeling voertuigen'},
    {t:'mc', v:'Vanaf welke leeftijd mag je zelfstandig rijden met rijbewijs B?', o:['16 jaar','17 jaar','18 jaar','21 jaar'], a:2, u:'Vanaf 18 jaar. Met 2toDrive mag je vanaf 17 rijden, maar alleen met een coach naast je.', art:'Reglement rijbewijzen'},
    {t:'jn', v:'Met rijbewijs B mag je een combinatie van 5.000 kg trekken.', a:1, u:'Nee. Met B is de combinatie maximaal 3.500 kg. Met code 96 tot 4.250 kg en met BE tot 7.000 kg.', art:'Reglement rijbewijzen'},
    {t:'mc', v:'Je verkoopt je auto. Wat moet je regelen?', o:['Niets','De auto vrijwaren bij de RDW','De verzekering doorgeven aan de koper','Het kenteken opsturen naar de gemeente'], a:1, u:'Zonder vrijwaringsbewijs blijf je aansprakelijk voor boetes, wegenbelasting en verzekering.', art:'WVW 1994, art. 50 en 51a'},
    {t:'mc', v:'Wanneer moet een nieuwe benzinepersonenauto voor het eerst op APK?', o:['Na één jaar','Na twee jaar','Na vier jaar','Na acht jaar'], a:2, u:'Een nieuwe benzineauto moet na vier jaar voor het eerst gekeurd. Diesel en LPG moeten eerder.', art:'Regeling voertuigen'},
    {t:'jn', v:'Rijden tijdens een ontzegging van de rijbevoegdheid is een misdrijf.', a:0, u:'Ja. Dat is strafbaar als misdrijf en kan leiden tot een celstraf.', art:'WVW 1994, art. 9'},
    {t:'fill', v:'Hoeveel jaar is een rijbewijs in principe geldig? (alleen het getal)', a:'10', u:'Tien jaar. Vanaf 70 jaar geldt een kortere termijn en zijn er extra keuringen.', art:'WVW 1994, art. 122'},
    {t:'mc', v:'Een agent vordert je rijbewijs in na een ernstige snelheidsovertreding. Wat betekent dat?', o:['Je mag voorlopig niet rijden met dat rijbewijs','Je krijgt alleen een boete','Je moet opnieuw examen doen','Je rijbewijs is definitief weg'], a:0, u:'Bij invordering raak je het rijbewijs tijdelijk kwijt; het Openbaar Ministerie beslist daarna wat er verder gebeurt.', art:'WVW 1994, art. 164'},
    {t:'multi', v:'Wat valt onder artikel 5 van de Wegenverkeerswet?', o:['Gevaar veroorzaken op de weg','Het verkeer hinderen','Te hard rijden met 3 km/h','Bumperkleven','Doorrijden na een ongeval'], a:[0,1,3], u:'Artikel 5 gaat over gevaar en hinder. Doorrijden na een ongeval valt onder artikel 7.', art:'WVW 1994, art. 5 en 7'},
    {t:'mc', v:'Hoeveel passagiers mag je naast jezelf vervoeren met rijbewijs B?', o:['Vier','Zes','Acht','Twaalf'], a:2, u:'Maximaal acht passagiers naast de bestuurder, mits er voor iedereen een zitplaats met gordel is.', art:'Reglement rijbewijzen'},
    {t:'jn', v:'Lading mag aan de voorkant van je auto uitsteken als je er een vlag aan hangt.', a:1, u:'Nee, niet zomaar. Achter mag lading maximaal één meter uitsteken, met markeringsbord. Aan de voorkant mag het alleen bij ondeelbare lading, en ook dan hooguit één meter.', art:'Regeling voertuigen, art. 5.18.12 en 5.18.13'},
    {t:'mc', v:'Wat gebeurt er bij het beginnersrijbewijspuntenstelsel na voldoende punten?', o:['Een hogere boete','Een verplicht onderzoek naar je rijvaardigheid en mogelijk ongeldigverklaring','Een waarschuwingsbrief','Niets bijzonders'], a:1, u:'Beginnende bestuurders die meerdere zware overtredingen begaan, moeten een onderzoek ondergaan; het rijbewijs kan ongeldig worden verklaard.', art:'WVW 1994, art. 130 t/m 134'},
    {t:'mc', v:'Wat heb je nodig om een caravan van 1.200 kg te trekken met een auto van 1.600 kg?', o:['Alleen rijbewijs B','Rijbewijs BE','Code 95','Niets, elke combinatie mag'], a:0, u:'De combinatie is 2.800 kg en blijft onder 3.500 kg, dus rijbewijs B volstaat. Let ook op de maximum trekgewichten van je auto.', art:'Reglement rijbewijzen'}
  ],
  puzzles:[]
},
{
  id:'voertuig', nr:8, titel:'Voertuigkennis', kleur:'--m-voertuig',
  samenvatting:'Dashboardlampjes, banden, remmen, verlichting, vloeistoffen en rijhulpsystemen (ADAS).',
  lessons:[
    {t:'Kleuren op je dashboard', b:'Rood betekent: stop zo snel mogelijk veilig en zet de motor uit. Oranje of geel betekent: er is iets mis, laat het nakijken. Groen en blauw zijn alleen informatie, zoals groot licht of richtingaanwijzer.', a:'Regeling voertuigen'},
    {t:'Rode lampjes die je niet mag negeren', b:'Oliedruk (oliekannetje), laadstroom (accu), koelvloeistoftemperatuur en het remsysteem. Doorrijden met een brandend oliedruklampje kan je motor binnen enkele kilometers vernielen.', a:'Regeling voertuigen'},
    {t:'Oranje lampjes', b:'Motorstoring (motorsymbool), ABS, ESP, bandenspanning en roetfilter. Je kunt meestal nog rijden, maar een systeem werkt niet of minder goed. Laat het snel nakijken.', a:'Regeling voertuigen'},
    {t:'Banden', b:'De wettelijke minimale profieldiepte is 1,6 millimeter. Voor winterbanden wordt vier millimeter aangeraden, maar dat is een advies. Controleer ook op scheuren en bobbels en op gelijkmatige slijtage.', a:'Regeling voertuigen, art. 5.2.27'},
    {t:'Remmen', b:'ABS voorkomt blokkeren zodat je kunt blijven sturen. De remassistent (BAS) versterkt je remkracht bij een noodstop. ESP of ESC remt individuele wielen af om slippen te voorkomen.', a:'Regeling voertuigen'},
    {t:'Verlichting controleren', b:'Dimlicht, groot licht, achterlicht, remlicht, richtingaanwijzers, kentekenverlichting en mistlicht moeten werken. Een kapot remlicht zie je zelf niet; laat iemand meekijken.', a:'RVV 1990, art. 32 t/m 41'},
    {t:'Vloeistoffen', b:'Motorolie, koelvloeistof, remvloeistof en ruitensproeiervloeistof controleer je regelmatig. Olie peil je op een vlakke ondergrond met koude motor.', a:'Regeling voertuigen'},
    {t:'Massa’s', b:'De massa ledig voertuig is het gewicht van de lege auto. De toegestane maximummassa is wat de auto maximaal mag wegen inclusief lading en inzittenden. Het verschil is je laadvermogen.', a:'Regeling voertuigen'},
    {t:'ADAS: rijhulpsystemen', b:'Adaptieve cruisecontrol houdt afstand, de rijstrookassistent stuurt je terug, dodehoekdetectie waarschuwt bij voertuigen naast je en de noodremassistent remt zelf. Ze ondersteunen, ze nemen het niet over.', a:'Regeling voertuigen en EU-verordening 2019/2144'},
    {t:'Je blijft verantwoordelijk', b:'Ook met ADAS aan ben jij de bestuurder. Een systeem kan uitvallen, een fietser missen of in slecht weer niet werken. Blijf kijken en hou je handen aan het stuur.', a:'WVW 1994, art. 5'},
    {t:'ISA: snelheidsassistent', b:'Nieuwe auto’s hebben een intelligente snelheidsassistent die waarschuwt als je te hard rijdt. Hij leest borden en kaartgegevens, en kan zich vergissen. De borden langs de weg zijn leidend.', a:'EU-verordening 2019/2144'},
    {t:'Elektrisch en hybride', b:'Een elektrische auto is stil, dus voetgangers horen je minder goed. Regeneratief remmen laadt de accu op als je gas loslaat; het remlicht gaat daarbij niet altijd aan.', a:'Regeling voertuigen'}
  ],
  questions:[
    {t:'mc', v:'Er gaat een rood oliedruklampje branden tijdens het rijden. Wat doe je?', o:['Doorrijden naar huis','Zo snel mogelijk veilig stoppen en de motor uitzetten','Olie bijvullen tijdens het rijden','Bij de volgende garage langs over een week'], a:1, u:'Een rood oliedruklampje betekent direct gevaar voor de motor. Stop veilig en zet de motor uit.', art:''},
    {t:'mc', v:'Wat betekent een oranje motorstoringslampje?', o:['Niets bijzonders','Er is een storing; laat het snel nakijken','Direct stoppen en motor uit','De motor is te koud'], a:1, u:'Oranje betekent: er is iets mis, maar je kunt meestal nog rijden. Laat het snel controleren.', art:''},
    {t:'fill', v:'Wat is de wettelijke minimale profieldiepte van een autoband in millimeters? (gebruik een komma, bijvoorbeeld 2,5)', a:'1,6', u:'1,6 millimeter. Onder die waarde is de band afgekeurd en neemt de grip op nat wegdek sterk af.', art:'Regeling voertuigen, art. 5.2.27'},
    {t:'mc', v:'Welke kleur dashboardlampje betekent dat je direct moet stoppen?', o:['Groen','Blauw','Oranje','Rood'], a:3, u:'Rood betekent een ernstig probleem: zoek een veilige plek, stop en zet de motor uit.', art:''},
    {t:'multi', v:'Welke van deze lampjes zijn rood en wijzen op een ernstig probleem?', o:['Oliedruk','Laadstroom (accu)','Richtingaanwijzer','Koelvloeistoftemperatuur','Remsysteem'], a:[0,1,3,4], u:'De richtingaanwijzer is een groen informatielampje. Bij oliedruk, koelvloeistof en remsysteem stop je direct; bij het accu-lampje rijd je op de accu en zoek je snel een garage, want na uitzetten start de auto mogelijk niet meer.', art:''},
    {t:'mc', v:'Wat doet ESP of ESC?', o:['Hij remt individuele wielen af om slippen te voorkomen','Hij houdt automatisch afstand','Hij parkeert de auto','Hij verwarmt de ruiten'], a:0, u:'ESP grijpt in als de auto dreigt te slippen door gericht af te remmen en het motorvermogen te verlagen.', art:''},
    {t:'jn', v:'Met adaptieve cruisecontrol hoef je niet meer op het verkeer te letten.', a:1, u:'Nee. ADAS ondersteunt je, maar jij blijft als bestuurder verantwoordelijk en moet blijven kijken.', art:'WVW 1994, art. 5'},
    {t:'mc', v:'Wat is dodehoekdetectie?', o:['Een spiegel zonder blinde vlek','Een systeem dat waarschuwt bij voertuigen naast of schuin achter je','Een extra achteruitrijcamera','Een systeem dat automatisch remt'], a:1, u:'Een waarschuwingssysteem, vaak met een lampje in de spiegel. Kijk nog steeds zelf over je schouder.', art:'EU-verordening 2019/2144'},
    {t:'mc', v:'Hoe peil je motorolie correct?', o:['Met warme motor tijdens het rijden','Op een vlakke ondergrond met koude of afgekoelde motor','Direct na het uitzetten van een hete motor','Terwijl de motor stationair draait'], a:1, u:'Op een vlakke ondergrond en met afgekoelde motor, zodat alle olie in het carter staat.', art:''},
    {t:'jn', v:'Een kapot remlicht merk je vanzelf tijdens het rijden.', a:1, u:'Nee. Je ziet je eigen remlichten niet. Laat iemand meekijken of gebruik de weerspiegeling in een ruit.', art:'Regeling voertuigen, afdeling 5.2'},
    {t:'mc', v:'Wat is het laadvermogen van een auto?', o:['De toegestane maximummassa','De massa ledig voertuig','Het verschil tussen toegestane maximummassa en massa ledig voertuig','Het gewicht van de aanhanger'], a:2, u:'Het laadvermogen is wat je nog mag meenemen aan lading en inzittenden.', art:''},
    {t:'mc', v:'Je rijstrookassistent stuurt je terug terwijl je bewust uitwijkt voor een obstakel. Wat doe je?', o:['Het stuur loslaten','Zelf sturen; jij hebt de leiding','De auto laten beslissen','Alarmlichten aan'], a:1, u:'Een rijstrookassistent kan je corrigeren, maar jij stuurt. Je kunt het systeem overrulen en zo nodig uitzetten.', art:'WVW 1994, art. 5'},
    {t:'jn', v:'Winterbanden worden afgeraden onder vier millimeter profiel.', a:0, u:'Ja. Wettelijk geldt 1,6 millimeter, maar voor winterbanden wordt vier millimeter aangehouden omdat de grip op sneeuw daaronder sterk afneemt.', art:'Advies van de bandenbranche; wettelijk geldt 1,6 mm'},
    {t:'mc', v:'Wat is bijzonder aan remmen in een elektrische auto?', o:['De remmen worden heter','Regeneratief remmen vertraagt al bij gas loslaten','Er is geen ABS','Je hebt geen remlicht nodig'], a:1, u:'Bij gas loslaten remt de auto al af en laadt hij de accu. Bij lichte vertraging gaan de remlichten niet aan, bij sterke vertraging wel. Kijk dus in je spiegel voor je sterk laat vertragen.', art:'Regeling voertuigen'},
    {t:'mc', v:'Je ziet een oranje lampje met een uitroepteken tussen haakjes. Wat is dit waarschijnlijk?', o:['Groot licht','Bandenspanning','Richtingaanwijzer','Mistlicht'], a:1, u:'Dat symbool staat meestal voor het bandenspanningscontrolesysteem. Controleer je spanning.', art:''},
    {t:'multi', v:'Welke verlichting moet werken bij een APK?', o:['Dimlicht','Remlicht','Kentekenverlichting','Interieurverlichting','Richtingaanwijzers'], a:[0,1,2,4], u:'Interieurverlichting hoort niet bij de verplichte voertuigverlichting.', art:'Regeling voertuigen'},
    {t:'mc', v:'Wat doet een noodremassistent (AEB)?', o:['Hij remt zelf als een botsing dreigt','Hij houdt je in je rijstrook','Hij parkeert de auto','Hij regelt je snelheid op de snelweg'], a:0, u:'AEB remt automatisch als het systeem een dreigende aanrijding detecteert. Het werkt niet in alle situaties.', art:'EU-verordening 2019/2144'},
    {t:'jn', v:'De snelheidsassistent (ISA) kan zich vergissen in de geldende maximumsnelheid.', a:0, u:'Ja. Het systeem leest borden en kaarten en kan fout zitten. De borden langs de weg zijn leidend.', art:'EU-verordening 2019/2144'},
    {t:'mc', v:'Je koelvloeistoftemperatuurlampje brandt rood. Wat doe je?', o:['Doorrijden met de kachel uit','Stoppen, motor uit en laten afkoelen','Direct koud water bijvullen op de hete motor','Harder rijden voor meer koeling'], a:1, u:'Stop en laat de motor afkoelen. Koud water op een hete motor kan de koppakking vernielen.', art:''},
    {t:'mc', v:'Waarom is een elektrische auto extra gevaarlijk voor voetgangers?', o:['Hij remt slechter','Hij is stil en dus slecht hoorbaar','Hij is zwaarder','Hij heeft geen verlichting'], a:1, u:'Voetgangers horen een elektrische auto bij lage snelheid nauwelijks. Nieuwe auto’s hebben daarom een kunstmatig geluid.', art:'EU-verordening 540/2014'},
    {t:'fill', v:'Welke kleur dashboardlampje is alleen informatie, zoals bij je richtingaanwijzer? (één woord)', a:'groen', u:'Groen en blauw zijn informatielampjes. Blauw is standaard voor groot licht.', art:''}
  ],
  puzzles:[]
}
];
